def comps_mask(arr, mask):
 seen=set(); ret=[]
 for r in range(arr.shape[0]):
  for c in range(arr.shape[1]):
   if not mask[r,c] or (r,c) in seen: continue
   q=[(r,c)]; seen.add((r,c)); co=[]
   while q:
    x,y=q.pop();co.append((x,y))
    for xx,yy in ((x-1,y),(x+1,y),(x,y-1),(x,y+1)):
     if 0<=xx<arr.shape[0] and 0<=yy<arr.shape[1] and mask[xx,yy] and (xx,yy) not in seen:seen.add((xx,yy));q.append((xx,yy))
   ret.append(co)
 return ret

