def spatial_voronoi(a,line,bg,metric='manhattan'):
 out=a.copy();fg=comps_mask(a,(a!=line)&(a!=bg)); ss=[]
 for co in fg:
  lab=Counter(a[x,y] for x,y in co).most_common(1)[0][0]
  ss.append((lab,co))
 for r,c in zip(*np.where(a==line)):
  dists=[]
  for lab,co in ss:
   if metric=='manhattan': d=min(abs(r-x)+abs(c-y) for x,y in co)
   elif metric=='cheb': d=min(max(abs(r-x),abs(c-y)) for x,y in co)
   else: d=min((r-x)**2+(c-y)**2 for x,y in co)
   dists.append((d,lab))
  d=min(x for x,l in dists); labs={l for dd,l in dists if dd==d}
  if len(labs)==1:out[r,c]=labs.pop()
 return out
